catalog_script_client.script:
function onChange(control, oldValue, newValue, isLoading) {

    // Don't run if the form is still loading or if the field is empty
    if (isLoading || !newValue) return;

    var today = new Date(); // current date
    var selected = new Date(newValue); // date the user selected

    // Strip time from both dates so we only compare dates, not times
    today.setHours(0, 0, 0, 0);
    selected.setHours(0, 0, 0, 0);

    if (selected < today) {
        // Clear the invalid date first, then show error so the message isn't wiped by the re-trigger
        g_form.setValue('start_date', '');
        // Show inline error message directly on the start_date field
        g_form.showFieldMsg('start_date', 'Start Date cannot be in the past.', 'error');

    } else {
        // Clear any existing error message if the date is valid
        g_form.clearMessages('start_date');
    }
}
